if(sub=='prog')return`${topbar('Progresso',"go('more')")}<div class="card"><div class="row">${sq(I('trophy',24))}<div class="grow"><div class="big">Nível ${lvl()}</div><div class="bar" style="margin-top:6px"><i style="width:${xp()%500/5}%"></i></div><small>${xp()%500} / 500 XP</small></div></div><p class="hint" style="margin:10px 0 0">1 minuto estudado = 1 XP. Revisão concluída = 20 XP.</p></div>
<div class="grid"><div class="card"><div class="big">${streak()}</div><small>dias seguidos</small></div><div class="card"><div class="big">${Math.max(longest(),streak())}</div><small>melhor sequência</small></div><div class="card"><div class="big">${hm(dur(()=>1))}</div><small>total estudado</small></div><div class="card"><div class="big">${S.sessions.length}</div><small>sessões</small></div></div>
<h2 style="margin:6px 0 4px">Conquistas</h2>${ht('Cada conquista é desbloqueada com seus registros reais.')}<div class="grid">${ACH().map(([i,n,d,v,t])=>`<div class="card ach ${v>=t?'':'off'}">${sq(I(i,22))}<b>${n}</b><small>${d}</small><div class="bar"><i style="width:${Math.min(100,v/t*100)}%"></i></div><small>${Math.min(Math.round(v),t)}/${t}${v>=t?', concluída':''}</small></div>`).join('')}</div>`;
